T['payment']=()=>`${notice('CORE-02: предлагаемая композиция ручного подтверждения оплаты. До утверждения процесса это не считается работающим платёжным сценарием.')}${steps(['Счёт','Подтверждение','Проверка','Решение'],1)}<div class="split">${panel('Заявка на проверку',`${dl([['Заказ','DM-0264'],['Счёт','INV-0264'],['Сумма',money(55950)]])}<hr class="rule">${field('Комментарий к подтверждению','','Дополнительное пояснение проверяющему, без банковских секретов.','textarea')}<div class="section">${upload()}</div>${actions('Отправить на проверку')}`)}${panel('Что произойдёт дальше',`<ol class="timeline"><li>Подтверждение загружено<small>Это не статус «Оплачено».</small></li><li>Проверка уполномоченным участником<small>Точная ответственность требует утверждения.</small></li><li>Принятие или отказ<small>Причина и история доступны сторонам.</small></li></ol>${badge('Внешний PSP не подключён','warn')}`)}</div>`;
