T['loading']=()=>`<div aria-busy="true" aria-label="Документы загружаются"><div class="toolbar"><div class="skeleton" style="width:50%"></div><div class="skeleton" style="width:25%"></div></div>${panel('',Array.from({length:5},()=>`<div class="skeleton tall"></div>`).join(''))}<p class="meta section">Загрузка документов…</p></div>`;
T['feedback']=()=>`<div class="atlas-grid">${panel('Результат и конфликт',`${banner('Изменения сохранены','Только после подтверждения необходимой серверной операции.','good')}${banner('Цена изменилась','17 900 → 18 900 ₸. Нужен отдельный акцепт.','warn')}${banner('Количество недоступно','Запрошено 3 уп., доступно 2. Измените количество явно.','bad')}${banner('Частичный результат','48 из 50 строк распознаны. Проверьте остальные.')}`)}${panel('Статусы с текстом',`<div class="spec-row">${badge('Черновик')}${badge('Сформирован','good')}${badge('На проверке','warn')}${badge('Отклонён','bad')}</div><p>Цвет не единственный носитель смысла. «Сформирован» не означает «Подписан» или «Оплачен».</p><hr class="rule"><div class="spec-label">Toast · открыто</div><div class="banner good"><div><strong>Черновик сохранён</strong><p>Решение ещё не отправлено клинике.</p></div></div>${btn('Показать toast','save-qty')}`)}${panel('Загрузка файла',`${file('invoice.pdf','Загрузка · 60%')}<div class="meter"><span style="width:60%"></span></div><p>Иллюстрация прогресса; настоящая загрузка не выполняется.</p>${file('invoice.exe','Ошибка формата')}<p class="red">Формат не поддерживается. Выберите другой файл.</p>${btn('Выбрать другой файл','upload')}`)}${panel('Skeleton и пустое состояние',`<div class="skeleton" style="width:50%"></div><div class="skeleton tall"></div><hr class="rule"><h3>Документов пока нет</h3><p>Документы появятся после соответствующих действий в заказе. Разрешённую загрузку можно выполнить вручную.</p>${link('buyer-document-upload','Загрузить документ','btn')}`)}</div>`;
T['navigation']=()=>`<div class="atlas-grid">${panel('Верхняя навигация',`<p>Одна оболочка для всех ролей. Основные разделы сверху; остальные — в «Ещё». Глобального sidebar нет.</p><div class="open-list">${link('buyer-orders','Заказы клиники','btn quiet')}${link('supplier-offers','Предложения поставщика','btn quiet')}${link('admin-overview','Очередь оператора','btn quiet')}</div><p>Прокрутите вниз и вверх: header скрывается и возвращается. Открытое меню и клавиатурный фокус удерживают шапку.</p>`)}${panel('Организация и город',`${select('Организация',['Демо-клиника 01','Демо-клиника 02'])}<div class="section open-list"><button type="button" class="selected" data-action="select-demo">Демо-клиника 01 · выбрана</button><button type="button" data-action="select-demo">Демо-клиника 02 · наблюдатель</button></div><div class="section">${select('Город',['Алматы','Астана','Шымкент'])}</div>`)}${panel('Период и multiselect',`${field('Период от','2026-09-01','Начало интервала по часовому поясу кабинета.','date')}<div class="calendar" aria-label="Сентябрь 2026 · пример календаря">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}${Array.from({length:30},(_,i)=>`<button type="button" class="${i===13?'selected':''}" data-action="date">${i+1}</button>`).join('')}</div><hr class="rule">${check('Терапия',true)}${check('Эндодонтия',true)}${check('Расходные материалы')}`)}${panel('Tabs, accordion, pagination',`${tabs(['Все','Активные','Архив'])}<details open><summary>Что означает «Опубликовано»?</summary><p>Предложение допущено к показу в пределах актуальных правил и данных. Это не гарантия наличия при будущем оформлении.</p></details>${pager(4)}<div class="section">${field('Поиск по списку','','Поиск не должен очищать выбранные значения.','search','placeholder="Номер или название"')}</div>`)}</div>`;
window.DM_EXTRA=T;
